public void makeDue(long executionId) {
  ensure(List.of(executionId));
  jdbc.update(
      "UPDATE cae_execution_poll_lease SET next_poll_at=UTC_TIMESTAMP(6)"
          + " WHERE execution_id=? AND (lease_until IS NULL OR lease_until<=UTC_TIMESTAMP(6))",
      executionId);
}
